begin;
alter table public.certificates add column generation_lease uuid,add column generation_lease_until timestamptz;
create or replace function public.portal_command_core(operation text,payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=private.require_actor();eid uuid:=nullif(payload->>'event_id','')::uuid;rid uuid:=nullif(payload->>'registration_id','')::uuid;tid uuid:=nullif(payload->>'team_id','')::uuid;e public.events;r public.registrations;t public.teams;target uuid;row_id uuid;record_status text;seat_count integer;members uuid[];member uuid;token text;new_state text;a public.attendance;template public.certificate_templates;cert public.certificates;reason text;
begin
 if operation='category_save' then
 if not private.has_role('admin') then raise exception 'Admin required' using errcode='42501';end if;
 if coalesce(payload->>'id','')='' then insert into public.event_categories(name) values(btrim(payload->>'name')) returning id into row_id;else update public.event_categories set name=btrim(payload->>'name'),active=coalesce((payload->>'active')::boolean,true) where id=(payload->>'id')::uuid returning id into row_id;end if;perform private.audit(operation,row_id);return jsonb_build_object('id',row_id);
 elsif operation='event_save' then
 if eid is null then if not(private.has_role('organizer') or private.has_role('admin')) then raise exception 'Organizer approval required' using errcode='42501';end if;
 insert into public.events(created_by,title,department,venue,contact,starts_at,ends_at,registration_opens_at,registration_closes_at,cancellation_closes_at,capacity)
 values(actor,payload->>'title',payload->>'department',payload->>'venue',payload->>'contact',(payload->>'starts_at')::timestamptz,(payload->>'ends_at')::timestamptz,(payload->>'registration_opens_at')::timestamptz,(payload->>'registration_closes_at')::timestamptz,(payload->>'cancellation_closes_at')::timestamptz,(payload->>'capacity')::integer) returning id into eid;
 insert into public.event_organizers values(eid,actor);
 else perform private.require_manager(eid);select * into e from public.events where id=eid for update;
 if e.status in('completed','cancelled') or e.attendance_finalized then raise exception 'Terminal/finalized event cannot be edited';end if;
 if exists(select 1 from public.registrations where event_id=eid and status<>'cancelled') and (e.mode is distinct from payload->>'mode' or e.min_team_size is distinct from coalesce((payload->>'min_team_size')::integer,2) or e.max_team_size is distinct from coalesce((payload->>'max_team_size')::integer,5) or e.attendance_mode is distinct from coalesce(payload->>'attendance_mode','event')) then raise exception 'Registration/attendance mode and team bounds are frozen after registrations';end if;
 if (payload->>'capacity')::integer<(select count(*) from public.registrations where event_id=eid and status='confirmed') then raise exception 'Capacity is below allocated seats';end if;end if;
 update public.events set title=btrim(payload->>'title'),short_description=coalesce(payload->>'short_description',''),description=coalesce(payload->>'description',''),category_id=nullif(payload->>'category_id','')::uuid,department=btrim(payload->>'department'),venue=btrim(payload->>'venue'),contact=btrim(payload->>'contact'),starts_at=(payload->>'starts_at')::timestamptz,ends_at=(payload->>'ends_at')::timestamptz,registration_opens_at=(payload->>'registration_opens_at')::timestamptz,registration_closes_at=(payload->>'registration_closes_at')::timestamptz,cancellation_closes_at=(payload->>'cancellation_closes_at')::timestamptz,capacity=(payload->>'capacity')::integer,
 mode=coalesce(payload->>'mode','individual'),min_team_size=coalesce((payload->>'min_team_size')::integer,2),max_team_size=coalesce((payload->>'max_team_size')::integer,5),waitlist_enabled=coalesce((payload->>'waitlist_enabled')::boolean,false),fee=coalesce((payload->>'fee')::numeric,0),certificate_enabled=coalesce((payload->>'certificate_enabled')::boolean,false),certificate_attendance_percent=coalesce((payload->>'certificate_attendance_percent')::integer,100),attendance_mode=coalesce(payload->>'attendance_mode','event'),feedback_requires_attendance=coalesce((payload->>'feedback_requires_attendance')::boolean,true),require_roster=coalesce((payload->>'require_roster')::boolean,false),eligible_departments=array(select jsonb_array_elements_text(coalesce(payload->'eligible_departments','[]'))),eligible_years=array(select jsonb_array_elements_text(coalesce(payload->'eligible_years','[]'))::integer),updated_at=now() where id=eid;
 perform private.audit(operation,eid);return jsonb_build_object('id',eid);
 elsif operation='event_transition' then perform private.require_manager(eid);select * into strict e from public.events where id=eid for update;new_state:=payload->>'status';
 if new_state='published' and e.status='draft' then
 if e.category_id is null or not exists(select 1 from public.event_categories where id=e.category_id and active) or char_length(btrim(e.description))<10 or char_length(btrim(e.venue))<2 or char_length(btrim(e.contact))<3 or char_length(btrim(e.department))<2 or e.registration_closes_at<=now() then raise exception 'Complete event details, active category and future registration close are required';end if;
 elsif new_state='completed' and e.status not in('draft','cancelled','completed') and now()>=e.ends_at then null;
 elsif new_state='registration_closed' and e.status='published' then null;
 elsif new_state='ongoing' and e.status in('published','registration_closed') and now()>=e.starts_at then null;
 elsif new_state='cancelled' and e.status not in('cancelled','completed') then if char_length(btrim(coalesce(payload->>'reason','')))<10 then raise exception 'Cancellation reason needs 10 characters';end if;
 else raise exception 'Invalid event state transition';end if;
 update public.events set status=new_state,updated_at=now() where id=eid;
 if new_state='cancelled' then update public.registrations set status='cancelled',updated_at=clock_timestamp() where event_id=eid and status<>'cancelled';update public.teams set status='cancelled' where event_id=eid;end if;
 perform private.audit('event.'||new_state,eid,jsonb_build_object('reason',payload->>'reason'));return jsonb_build_object('id',eid);
 elsif operation in('session_save','session_delete') then perform private.require_manager(eid);select * into strict e from public.events where id=eid for update;if e.attendance_finalized or e.status in('completed','cancelled') or exists(select 1 from public.attendance where event_id=eid) then raise exception 'Sessions are frozen after attendance starts';end if;
 row_id:=nullif(payload->>'id','')::uuid;
 if operation='session_delete' then delete from public.event_sessions where id=row_id and event_id=eid;return '{}'::jsonb;end if;
 if (payload->>'starts_at')::timestamptz<e.starts_at or (payload->>'ends_at')::timestamptz>e.ends_at then raise exception 'Session must be within event times';end if;
 if row_id is null then row_id:=gen_random_uuid();end if;
 if exists(select 1 from public.event_sessions where id=row_id and event_id<>eid) then raise exception 'Session access denied';end if;
 insert into public.event_sessions(id,event_id,title,description,starts_at,ends_at,venue,speaker,display_order) values(row_id,eid,payload->>'title',coalesce(payload->>'description',''),(payload->>'starts_at')::timestamptz,(payload->>'ends_at')::timestamptz,payload->>'venue',coalesce(payload->>'speaker',''),coalesce((payload->>'display_order')::integer,0)) on conflict(id) do update set title=excluded.title,description=excluded.description,starts_at=excluded.starts_at,ends_at=excluded.ends_at,venue=excluded.venue,speaker=excluded.speaker,display_order=excluded.display_order;
 return jsonb_build_object('id',row_id,'overlap_warning',exists(select 1 from public.event_sessions s where s.id<>row_id and s.venue=payload->>'venue' and tstzrange(s.starts_at,s.ends_at,'[)')&&tstzrange((payload->>'starts_at')::timestamptz,(payload->>'ends_at')::timestamptz,'[)')));
 elsif operation='assign_organizer' then perform private.require_manager(eid);target:=(payload->>'user_id')::uuid;if not exists(select 1 from public.user_roles where user_id=target and role='organizer') then raise exception 'Target needs approved organizer role';end if;insert into public.event_organizers values(eid,target) on conflict do nothing;perform private.audit(operation,eid,jsonb_build_object('user_id',target));return '{}'::jsonb;
 elsif operation='poster_set' then perform private.require_manager(eid);if payload->>'path' not like eid::text||'/%' then raise exception 'Invalid event poster path';end if;update public.events set poster_path=payload->>'path' where id=eid;return '{}'::jsonb;
 elsif operation='team_create' then select * into strict e from public.events where id=eid for update;if e.mode<>'team' or e.status<>'published' or now()>e.registration_closes_at then raise exception 'Team creation unavailable';end if;insert into public.teams(event_id,name,leader_id) values(eid,payload->>'name',actor) returning id into tid;insert into public.team_members values(tid,eid,actor,'accepted');return jsonb_build_object('id',tid);
 elsif operation in('team_invite','team_accept','team_decline') then
 select event_id into strict eid from public.teams where id=tid;select * into strict e from public.events where id=eid for update;select * into strict t from public.teams where id=tid for update;
 if t.status<>'draft' or e.status<>'published' or now()>e.registration_closes_at then raise exception 'Team membership is frozen';end if;
 if operation='team_invite' then if t.leader_id<>actor then raise exception 'Only the leader may invite';end if;
 if (select count(*) from public.team_members where team_id=tid)>=e.max_team_size then raise exception 'Team maximum reached';end if;
 select p.id into target from public.profiles p join auth.users u on u.id=p.id where p.email=lower(btrim(payload->>'email')) and u.email_confirmed_at is not null and p.is_active;
 if target is null then raise exception 'Verified account unavailable';end if;
 insert into public.team_members values(tid,eid,target,'invited');perform private.notify(target,eid,'Team invitation','A team invitation is ready for your review.','team:'||tid||':'||target);return '{}'::jsonb;
 elsif operation='team_accept' then update public.team_members set status='accepted' where team_id=tid and user_id=actor and status='invited';
 else if t.leader_id=actor then raise exception 'Leader cannot decline their own team';end if;delete from public.team_members where team_id=tid and user_id=actor and status='invited';end if;return '{}'::jsonb;
 elsif operation='register' then select * into strict e from public.events where id=eid for update;
 if e.status<>'published' or now()<e.registration_opens_at or now()>e.registration_closes_at then raise exception 'Registration is not open';end if;if e.fee>0 then raise exception 'Online fee collection is not configured; paid registration cannot proceed';end if;
 if e.mode='team' then select * into strict t from public.teams where id=tid and event_id=eid and leader_id=actor for update;if t.status='registered' then raise exception 'Team already registered';end if;
 if exists(select 1 from public.team_members where team_id=tid and status<>'accepted') then raise exception 'Every team invitation must be accepted';end if;
 select array_agg(user_id) into members from public.team_members where team_id=tid and status='accepted';if coalesce(cardinality(members),0) not between e.min_team_size and e.max_team_size then raise exception 'Invalid team size';end if;
 else if tid is not null then raise exception 'Individual event does not accept teams';end if;members:=array[actor];end if;
 foreach member in array members loop if not private.eligible(e,member) then raise exception 'Participant not eligible';end if;if exists(select 1 from public.registrations where event_id=eid and user_id=member and status<>'cancelled') then raise exception 'Duplicate registration';end if;end loop;
 select count(*) into seat_count from public.registrations where event_id=eid and status='confirmed';record_status:='confirmed';
 if seat_count+cardinality(members)>e.capacity or exists(select 1 from public.registrations where event_id=eid and status='waitlisted') then if not e.waitlist_enabled then raise exception 'Event is full';end if;record_status:='waitlisted';end if;
 foreach member in array members loop insert into public.registrations(event_id,user_id,team_id,status) values(eid,member,tid,record_status) on conflict(event_id,user_id) do update set status=excluded.status,team_id=excluded.team_id,created_at=clock_timestamp(),updated_at=clock_timestamp() returning id into row_id;if member=actor then rid:=row_id;end if;end loop;
 if tid is not null then update public.teams set status='registered' where id=tid;end if;return jsonb_build_object('id',rid,'status',record_status);
 elsif operation='cancel_registration' then select event_id into strict eid from public.registrations where id=rid;select * into strict e from public.events where id=eid for update;select * into strict r from public.registrations where id=rid for update;
 if not private.can_manage(eid) then if r.user_id<>actor or now()>e.cancellation_closes_at then raise exception 'Cancellation not permitted';end if;if r.team_id is not null and not exists(select 1 from public.teams where id=r.team_id and leader_id=actor) then raise exception 'Team leader must cancel the whole team';end if;end if;
 if e.attendance_finalized or exists(select 1 from public.certificates where registration_id=rid and status='issued') then raise exception 'Cannot cancel finalized participation';end if;
 update public.registrations set status='cancelled',updated_at=clock_timestamp() where id=rid or (r.team_id is not null and team_id=r.team_id);
 if r.team_id is not null then update public.teams set status='cancelled' where id=r.team_id;end if;perform private.promote_waitlist(eid);return '{}'::jsonb;
 elsif operation='promote_waitlist' then perform private.require_manager(eid);perform private.promote_waitlist(eid);return '{}'::jsonb;
 elsif operation='notification_read' then update public.notifications set read_at=now() where id=(payload->>'id')::uuid and user_id=actor;return '{}'::jsonb;
 elsif operation='event_message' then perform private.require_manager(eid);if char_length(btrim(coalesce(payload->>'message','')))<5 or char_length(payload->>'message')>5000 then raise exception 'Message must be 5–5000 characters';end if;row_id:=gen_random_uuid();for target in select user_id from public.registrations where event_id=eid and status<>'cancelled' loop perform private.notify(target,eid,'Event update',payload->>'message','message:'||row_id);end loop;perform private.audit(operation,eid);return '{}'::jsonb;
 elsif operation='qr_token' then select r0.* into strict r from public.registrations r0 where r0.id=rid and r0.user_id=actor and r0.status='confirmed';select * into strict e from public.events where id=r.event_id;if e.status in('cancelled','completed') then raise exception 'Check-in unavailable';end if;token:=encode(extensions.gen_random_bytes(32),'hex');insert into public.checkin_tokens values(rid,extensions.digest(token,'sha256'),e.ends_at+interval '1 day') on conflict(registration_id) do update set token_hash=excluded.token_hash,expires_at=excluded.expires_at;return jsonb_build_object('token',token,'event_id',e.id);
 elsif operation in('attendance_scan','attendance_manual','attendance_correct','attendance_finalize') then perform private.require_manager(eid);select * into strict e from public.events where id=eid for update;
 if operation='attendance_finalize' then if e.status<>'completed' then raise exception 'Complete event before finalizing attendance';end if;update public.events set attendance_finalized=true where id=eid;perform private.audit(operation,eid);return '{}'::jsonb;end if;
 if e.attendance_finalized or e.status in('draft','cancelled') then raise exception 'Attendance is locked';end if;if now()<e.starts_at or now()>e.ends_at+interval '1 day' then raise exception 'Check-in outside allowed event window';end if;
 if operation='attendance_correct' then select * into strict a from public.attendance where id=(payload->>'id')::uuid and event_id=eid for update;reason:=btrim(payload->>'reason');insert into public.attendance_corrections(attendance_id,actor_id,previous_present,new_present,reason) values(a.id,actor,a.present,(payload->>'present')::boolean,reason);update public.attendance set present=(payload->>'present')::boolean where id=a.id;perform private.audit(operation,a.id,jsonb_build_object('reason',reason));return '{}'::jsonb;end if;
 if operation='attendance_scan' then select rr.* into strict r from public.checkin_tokens tk join public.registrations rr on rr.id=tk.registration_id where tk.token_hash=extensions.digest(payload->>'token','sha256') and tk.expires_at>now() and rr.event_id=eid;rid:=r.id;end if;
 select * into strict r from public.registrations where id=rid and event_id=eid and status='confirmed';row_id:=nullif(payload->>'session_id','')::uuid;
 if (e.attendance_mode='session' and row_id is null) or (e.attendance_mode='event' and row_id is not null) then raise exception 'Attendance scope mismatch';end if;
 insert into public.attendance(registration_id,event_id,session_id,recorded_by) values(rid,eid,row_id,actor) returning id into target;perform private.notify(r.user_id,eid,'Attendance confirmed','Your attendance was recorded.','attendance:'||target);return jsonb_build_object('id',target,'reference',r.reference);
 elsif operation='feedback_submit' then select * into strict e from public.events where id=eid;if e.status<>'completed' then raise exception 'Feedback opens after completion';end if;select * into strict r from public.registrations where event_id=eid and user_id=actor and status='confirmed';if e.feedback_requires_attendance and private.attendance_percent(r.id)<=0 then raise exception 'Attendance required for feedback';end if;
 insert into public.event_feedback(event_id,user_id,overall,organization,content,venue,comments,suggestions,attend_future) values(eid,actor,(payload->>'overall')::integer,(payload->>'organization')::integer,(payload->>'content')::integer,(payload->>'venue')::integer,coalesce(payload->>'comments',''),coalesce(payload->>'suggestions',''),(payload->>'attend_future')::boolean) returning id into row_id;return jsonb_build_object('id',row_id);
 elsif operation='template_save' then if not private.has_role('admin') then raise exception 'Admin required';end if;insert into public.certificate_templates(name,institution,signatory_name,signatory_title,body,approved_by) values(payload->>'name',payload->>'institution',payload->>'signatory_name',payload->>'signatory_title',payload->>'body',actor) returning id into row_id;perform private.audit(operation,row_id);return jsonb_build_object('id',row_id);
 elsif operation='certificate_prepare' then select event_id into strict eid from public.registrations where id=rid;perform private.require_manager(eid);select * into strict e from public.events where id=eid for update;select * into strict r from public.registrations where id=rid and status='confirmed';
 if e.status<>'completed' or not e.attendance_finalized or not e.certificate_enabled or private.attendance_percent(rid)<e.certificate_attendance_percent then raise exception 'Participant not eligible for certificate';end if;select * into strict template from public.certificate_templates where id=(payload->>'template_id')::uuid and active;reason:=btrim(payload->>'reason');if char_length(coalesce(reason,''))<10 then raise exception 'Issuance approval reason required';end if;
 insert into public.certificates(registration_id,user_id,event_id,template_id,type,snapshot,approved_by,approval_reason) select rid,r.user_id,eid,template.id,payload->>'type',jsonb_build_object('participant',p.full_name,'event',e.title,'institution',template.institution,'signatory_name',template.signatory_name,'signatory_title',template.signatory_title,'body',template.body),actor,reason from public.profiles p where p.id=r.user_id on conflict(registration_id,type) do nothing;
 select * into strict cert from public.certificates where registration_id=rid and type=payload->>'type';if cert.status='revoked' then raise exception 'Revoked certificate cannot be reissued through retry';end if;perform private.audit(operation,cert.id);return to_jsonb(cert);
 elsif operation='certificate_revoke' then select * into strict cert from public.certificates where id=(payload->>'id')::uuid;perform private.require_manager(cert.event_id);reason:=btrim(payload->>'reason');if char_length(coalesce(reason,''))<10 then raise exception 'Revocation reason required';end if;update public.certificates set status='revoked',revoked_at=now(),revocation_reason=reason where id=cert.id;perform private.audit(operation,cert.id,jsonb_build_object('reason',reason));return '{}'::jsonb;
 elsif operation='role_set' then if not private.has_role('admin') then raise exception 'Admin required';end if;target:=(payload->>'user_id')::uuid;if target=actor then raise exception 'Use another authorized admin for self-role changes';end if;
 if not exists(select 1 from public.profiles p join auth.users u on u.id=p.id where p.id=target and p.is_active and u.email_confirmed_at is not null) then raise exception 'Active verified account required';end if;
 if (payload->>'enabled')::boolean then insert into public.user_roles(user_id,role,granted_by) values(target,(payload->>'role')::public.app_role,actor) on conflict do nothing;else delete from public.user_roles where user_id=target and role=(payload->>'role')::public.app_role;end if;return '{}'::jsonb;
 elsif operation='account_set_active' then if not private.has_role('admin') then raise exception 'Admin required';end if;target:=(payload->>'user_id')::uuid;if target=actor then raise exception 'Cannot deactivate self';end if;update public.profiles set is_active=(payload->>'active')::boolean where id=target;perform private.audit(operation,target,payload-'user_id');return '{}'::jsonb;
 elsif operation='roster_upsert' then if not private.has_role('admin') then raise exception 'Admin required';end if;insert into public.student_roster(rrn,department,study_year,active,source_authority,verified_by) values(payload->>'rrn',payload->>'department',(payload->>'study_year')::integer,(payload->>'active')::boolean,payload->>'source_authority',actor) on conflict(rrn) do update set department=excluded.department,study_year=excluded.study_year,active=excluded.active,source_authority=excluded.source_authority,verified_by=actor,updated_at=now();perform private.audit(operation,actor,jsonb_build_object('source_authority',payload->>'source_authority'));return '{}'::jsonb;
 elsif operation='settings_save' then if not private.has_role('admin') then raise exception 'Admin required';end if;if payload->>'key' not in('support_email','institution_timezone','reminder_hours') then raise exception 'Unsupported setting';end if;
 if payload->>'key'='institution_timezone' and payload->>'value'<>'Asia/Kolkata' then raise exception 'Institution timezone is Asia/Kolkata in this release';end if;if payload->>'key'='reminder_hours' and (payload->>'value')::integer not between 1 and 168 then raise exception 'Reminder hours must be 1–168';end if;
 insert into public.platform_settings(key,value,updated_by) values(payload->>'key',payload->'value',actor) on conflict(key) do update set value=excluded.value,updated_by=actor,updated_at=now();perform private.audit(operation,actor,jsonb_build_object('key',payload->>'key'));return '{}'::jsonb;
 else raise exception 'Unknown operation';end if;
end;$$;

create or replace function public.portal_command(operation text,payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=private.require_actor();rid uuid;request public.organizer_requests;certificate public.certificates;prepared jsonb;begin
 perform private.consume_limit(operation);
 begin
 if operation='request_organizer' then insert into public.organizer_requests(user_id,reason) values(actor,payload->>'reason') returning id into rid;return jsonb_build_object('id',rid);
 elsif operation='review_organizer' then if not private.has_role('admin') then raise exception 'Admin required';end if;select * into strict request from public.organizer_requests where id=(payload->>'id')::uuid and status='pending' for update;
 if request.user_id=actor then raise exception 'Cannot approve own request';end if;if char_length(btrim(coalesce(payload->>'note','')))<10 then raise exception 'Review note required';end if;
 if (payload->>'approve')::boolean then perform public.portal_command_core('role_set',jsonb_build_object('user_id',request.user_id,'role','organizer','enabled',true));end if;
 update public.organizer_requests set status=case when(payload->>'approve')::boolean then 'approved' else 'rejected' end,reviewed_by=actor,review_note=payload->>'note',reviewed_at=now() where id=request.id;perform private.audit(operation,request.id);return '{}'::jsonb;
 elsif operation='support_report' then insert into public.support_issues(user_id,subject,description) values(actor,payload->>'subject',payload->>'description') returning id into rid;return jsonb_build_object('id',rid);
 elsif operation='support_resolve' then if not private.has_role('admin') then raise exception 'Admin required';end if;if char_length(btrim(coalesce(payload->>'resolution','')))<10 then raise exception 'Resolution note required';end if;update public.support_issues set status='resolved',resolution=payload->>'resolution',reviewed_by=actor where id=(payload->>'id')::uuid;perform private.audit(operation,(payload->>'id')::uuid);return '{}'::jsonb;
 elsif operation='certificate_prepare' then
 prepared:=public.portal_command_core(operation,payload);
 select * into strict certificate from public.certificates where id=(prepared->>'id')::uuid for update;
 if certificate.status='issued' then return to_jsonb(certificate);end if;
 if certificate.generation_lease_until>now() then raise exception 'Certificate generation is already in progress. Retry after five minutes if it fails.';end if;
 update public.certificates set generation_lease=gen_random_uuid(),generation_lease_until=now()+interval '5 minutes' where id=certificate.id returning * into certificate;return to_jsonb(certificate);
 elsif operation='template_deactivate' then if not private.has_role('admin') then raise exception 'Admin required';end if;update public.certificate_templates set active=false where id=(payload->>'id')::uuid;if not found then raise exception 'Template not found';end if;perform private.audit(operation,(payload->>'id')::uuid);return '{}'::jsonb;
 else return public.portal_command_core(operation,payload);end if;
 exception when others then return jsonb_build_object('error',sqlerrm,'code',sqlstate);end;
 end;$$;
create or replace function public.complete_certificate(certificate_id uuid,storage_path text,document_issued_at timestamptz default now()) returns void language plpgsql security definer set search_path='' as $$declare c public.certificates;e public.events;begin
 select event_id into strict e.id from public.certificates where id=certificate_id;select * into strict e from public.events where id=e.id for update;select * into strict c from public.certificates where id=certificate_id for update;
 if document_issued_at>now()+interval '1 minute' or document_issued_at<now()-interval '15 minutes' then raise exception 'Certificate document timestamp is stale';end if;
 if storage_path<>c.user_id::text||'/'||c.id::text||'.pdf' then raise exception 'Invalid private certificate path';end if;
 if c.status='issued' and c.object_path=storage_path then return;end if;
 if c.generation_lease_until<now() or c.generation_lease is null then raise exception 'Certificate generation lease expired';end if;
 if c.status<>'pending' or e.status<>'completed' or not e.attendance_finalized or private.attendance_percent(c.registration_id)<e.certificate_attendance_percent or not exists(select 1 from public.registrations where id=c.registration_id and status='confirmed') then raise exception 'Certificate finalization denied';end if;
 update public.certificates set object_path=storage_path,status='issued',issued_at=document_issued_at where id=c.id;perform private.audit('certificate.issued',c.id,jsonb_build_object('approved_by',c.approved_by));perform private.notify(c.user_id,c.event_id,'Certificate available','Your approved certificate is ready to download.','certificate:'||c.id);end;$$;
revoke all on function public.portal_command_core(text,jsonb) from public,anon,authenticated;
commit;
